// Age and sex rows are generated by code from the registry's structured
// fields, never by the LLM (Addendum G4).
import type { Criterion, Rule, Trial } from "../types";

const empty = { en: "", es: "" };
const noAlts = { en: [], es: [] };

export const AGE_ID = "IN-AGE";
export const SEX_ID = "IN-SEX";

function fmt(n: number) {
  return Number.isInteger(n) ? String(n) : n.toFixed(1);
}

export function ageCriterion(trial: Trial, bulletIds: string[] = []): Criterion | null {
  const { minAgeYears: min, maxAgeYears: max } = trial;
  if (min === undefined && max === undefined) return null;

  let rule: Rule;
  let source: string;
  if (min !== undefined && max !== undefined) {
    rule = { op: "between", min, max };
    source = `Registry age limits: ${fmt(min)} to ${fmt(max)} years`;
  } else if (min !== undefined) {
    rule = { op: "gte", value: min };
    source = `Registry age limit: ${fmt(min)} years or older`;
  } else {
    rule = { op: "lte", value: max! };
    source = `Registry age limit: ${fmt(max!)} years or younger`;
  }

  return {
    id: AGE_ID,
    kind: "inclusion",
    bulletIds,
    sourceText: source,
    mode: "ask",
    question: { en: "How old are you?", es: "¿Cuántos años tiene?" },
    questionProxy: {
      en: "How old is the person you're calling for?",
      es: "¿Cuántos años tiene la persona por la que llama?",
    },
    altPhrasings: {
      en: ["What is your age in years?"],
      es: ["¿Qué edad tiene, en años?"],
    },
    answerType: "number",
    unit: "years",
    enumOptions: [],
    rule,
    readBackText: {
      en: "So you are {answer} years old — is that right?",
      es: "Entonces, usted tiene {answer} años, ¿es correcto?",
    },
    readBackTextProxy: {
      en: "So they are {answer} years old — is that right?",
      es: "Entonces, esa persona tiene {answer} años, ¿es correcto?",
    },
    groupId: null,
    registryDerived: true,
    siteCheckNote: "",
  };
}

export function sexCriterion(trial: Trial, bulletIds: string[] = []): Criterion | null {
  if (trial.sex === "ALL") return null;
  const female = trial.sex === "FEMALE";
  const word = { en: female ? "female" : "male", es: female ? "femenino" : "masculino" };

  // Gender-based eligibility can't be reduced to a yes/no on sex at birth.
  if (trial.genderBased) {
    return {
      id: SEX_ID,
      kind: "inclusion",
      bulletIds,
      sourceText: `Registry sex: ${trial.sex}; gender-based: ${trial.genderDescription ?? "yes"}`,
      mode: "confirm_at_site",
      question: empty,
      questionProxy: empty,
      altPhrasings: noAlts,
      answerType: null,
      unit: null,
      enumOptions: [],
      rule: null,
      readBackText: empty,
      readBackTextProxy: empty,
      groupId: null,
      registryDerived: true,
      siteCheckNote: trial.genderDescription ?? "Gender-based eligibility — confirm at site.",
    };
  }

  return {
    id: SEX_ID,
    kind: "inclusion",
    bulletIds,
    sourceText: `Registry sex: ${trial.sex}`,
    mode: "ask",
    question: {
      en: `This study is for people assigned ${word.en} at birth. Does that apply to you?`,
      es: `Este estudio es para personas a las que se les asignó el sexo ${word.es} al nacer. ¿Esto aplica en su caso?`,
    },
    questionProxy: {
      en: `This study is for people assigned ${word.en} at birth. Does that apply to the person you're calling for?`,
      es: `Este estudio es para personas a las que se les asignó el sexo ${word.es} al nacer. ¿Esto aplica a la persona por la que llama?`,
    },
    altPhrasings: noAlts,
    answerType: "yes_no",
    unit: null,
    enumOptions: [],
    rule: { op: "eq", value: true },
    readBackText: {
      en: "So that does not apply to you — is that right?",
      es: "Entonces, eso no aplica en su caso, ¿es correcto?",
    },
    readBackTextProxy: {
      en: "So that does not apply to them — is that right?",
      es: "Entonces, eso no aplica a esa persona, ¿es correcto?",
    },
    groupId: null,
    registryDerived: true,
    siteCheckNote: "",
  };
}

/**
 * Replace any registry-derived rows with freshly generated ones, keeping the
 * bullet links already attached to them. Derived rows always come first.
 */
export function withDerivedRows(
  trial: Trial,
  criteria: Criterion[],
  links: { age?: string[]; sex?: string[] } = {},
): Criterion[] {
  const prevAge = criteria.find((c) => c.id === AGE_ID)?.bulletIds;
  const prevSex = criteria.find((c) => c.id === SEX_ID)?.bulletIds;
  const rest = criteria.filter((c) => !c.registryDerived);
  const age = ageCriterion(trial, links.age ?? prevAge ?? []);
  const sex = sexCriterion(trial, links.sex ?? prevSex ?? []);
  return [...(age ? [age] : []), ...(sex ? [sex] : []), ...rest];
}
